<?php
require 'helpers.php'; requerirLogin();
if (!puede('ver_dashboard')) { http_response_code(403); exit('Sin permiso.'); }
$clienteId=(int)usuario()['cliente_id']; $error=''; $ok='';
$st=db()->prepare('SELECT id,nombre,unidad,moneda,precio_manual,margen_porcentaje,volumen_esperado FROM costobene_productos WHERE cliente_id=? ORDER BY nombre');$st->execute([$clienteId]);$productos=$st->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST') { try {
 validarCsrf('csrf_promociones'); $accion=(string)($_POST['accion']??'');
 if($accion==='margen') { if(!esAdministrador()) throw new RuntimeException('Solo el administrador puede cambiar el margen mínimo.'); $margen=filter_var($_POST['margen_minimo']??null,FILTER_VALIDATE_FLOAT); if($margen===false||$margen<0||$margen>90) throw new RuntimeException('El margen mínimo debe estar entre 0 y 90%.'); $up=db()->prepare('UPDATE costobene_clientes SET margen_minimo=? WHERE id=?');$up->execute([$margen,$clienteId]);$ok='Margen mínimo actualizado.'; }
 if($accion==='crear') {
  if(!puede('gestionar_promociones')) throw new RuntimeException('Tu perfil no puede crear promociones.');
  $nombre=trim((string)($_POST['nombre']??''));$tipo=(string)($_POST['tipo']??'');$alcance=(string)($_POST['alcance']??'');$valor=filter_var($_POST['valor']??null,FILTER_VALIDATE_FLOAT);
  $inicio=(string)($_POST['fecha_inicio']??'');$fin=(string)($_POST['fecha_fin']??'');$ids=$_POST['productos']??[];
  if($nombre===''||mb_strlen($nombre)>150||!in_array($tipo,['porcentaje','fijo','mayorista','combo'],true)||!in_array($alcance,['individual','todos'],true)||$valor===false||$valor<=0) throw new RuntimeException('Completá correctamente nombre, tipo, alcance y valor.');
  if(in_array($tipo,['porcentaje','mayorista'],true)&&$valor>100) throw new RuntimeException('El descuento porcentual no puede superar el 100%.');
  $d1=DateTime::createFromFormat('Y-m-d',$inicio);$d2=DateTime::createFromFormat('Y-m-d',$fin);if(!$d1||!$d2||$d2<$d1) throw new RuntimeException('Las fechas de vigencia no son válidas.');
  $minimo=$tipo==='mayorista'?filter_var($_POST['cantidad_minima']??null,FILTER_VALIDATE_FLOAT):null;$bonif=$tipo==='combo'?filter_var($_POST['cantidad_bonificada']??null,FILTER_VALIDATE_FLOAT):null;
  if($tipo==='mayorista'&&(!$minimo||$minimo<=0)) throw new RuntimeException('Ingresá una cantidad mínima válida para el precio mayorista.');
  if($tipo==='combo'&&(!$bonif||$bonif<=0)) throw new RuntimeException('Ingresá una cantidad bonificada válida para el combo.');
  $include=isset($_POST['incluir_futuros'])?1:0;
  $pdo=db();$pdo->beginTransaction();
  if($alcance==='individual') { if(!is_array($ids)||!$ids) throw new RuntimeException('Seleccioná al menos un producto o servicio.');$ids=array_values(array_unique(array_filter(array_map('intval',$ids))));$ph=implode(',',array_fill(0,count($ids),'?'));$check=$pdo->prepare("SELECT id,nombre,precio_manual,margen_porcentaje,volumen_esperado FROM costobene_productos WHERE cliente_id=? AND id IN ($ph)");$check->execute(array_merge([$clienteId],$ids));$targets=$check->fetchAll();if(count($targets)!==count($ids))throw new RuntimeException('La selección contiene elementos que no pertenecen a tu empresa.'); }
  else { $targets=$productos; }
  // No permitir descuentos que produzcan precios negativos. Cuando hay precio manual, se controla contra margen mínimo configurado.
  $m=$pdo->prepare('SELECT margen_minimo FROM costobene_clientes WHERE id=?');$m->execute([$clienteId]);$margenMin=(float)$m->fetchColumn();
  foreach($targets as $t){
   $precio=(float)($t['precio_manual']??0);$volumen=max(0.0,(float)($t['volumen_esperado']??0));
   $costQ=$pdo->prepare("SELECT c.tipo_costo,COALESCE(SUM(COALESCE(m.monto_asignado,c.monto)),0) total FROM costobene_costos_producto c LEFT JOIN costobene_costos_productos_compartidos m ON m.costo_id=c.id AND m.producto_id=? WHERE c.estado_aprobacion='aprobado' AND (m.producto_id IS NOT NULL OR (c.producto_id=? AND NOT EXISTS (SELECT 1 FROM costobene_costos_productos_compartidos mx WHERE mx.costo_id=c.id))) GROUP BY c.tipo_costo");$costQ->execute([(int)$t['id'],(int)$t['id']]);$sums=['fixed'=>0,'variable'=>0,'indirect'=>0,'labor'=>0];foreach($costQ as $cx)$sums[$cx['tipo_costo']]=(float)$cx['total'];$unitCost=($volumen>0?(($sums['fixed']+$sums['indirect']+$sums['labor'])/$volumen):0)+$sums['variable'];
   if($precio<=0 && $unitCost>0){$margenProducto=(float)($t['margen_porcentaje']??30)/100;$precio=$margenProducto<1?$unitCost/(1-$margenProducto):$unitCost;}
   if($precio>0){$nuevo=$precio;if($tipo==='porcentaje'||$tipo==='mayorista')$nuevo=$precio*(1-$valor/100);elseif($tipo==='fijo')$nuevo=$precio-$valor;elseif($tipo==='combo'&&$valor>0&&$bonif>0)$nuevo=$precio*$valor/($valor+$bonif);if($nuevo<0)throw new RuntimeException('El descuento supera el precio de '.$t['nombre'].'.');if(in_array($tipo,['porcentaje','mayorista'],true)&&$valor>100)throw new RuntimeException('El descuento porcentual no puede superar el 100%.');if($unitCost>0&&$nuevo>0){$margenReal=(($nuevo-$unitCost)/$nuevo)*100;if($margenReal+0.0001<$margenMin)throw new RuntimeException('La promoción dejaría el margen de '.$t['nombre'].' por debajo del mínimo de '.$margenMin.'%.');}}
  }
  // Estado inicial neutro; el estado visible se calcula según fechas y pausas.
  $st=$pdo->prepare("INSERT INTO costobene_promociones (cliente_id,nombre,tipo,alcance,valor,cantidad_minima,cantidad_bonificada,incluir_futuros,fecha_inicio,fecha_fin,estado,creado_por) VALUES (?,?,?,?,?,?,?,?,?,?,'programada',?)");
  $st->execute([$clienteId,$nombre,$tipo,$alcance,$valor,$minimo,$bonif,$include,$inicio,$fin,(int)usuario()['id']]);$promoId=(int)$pdo->lastInsertId();
  if($alcance==='individual'){$ins=$pdo->prepare('INSERT INTO costobene_promociones_productos(promocion_id,producto_id) VALUES(?,?)');foreach($ids as $id)$ins->execute([$promoId,$id]);} else { $ins=$pdo->prepare('INSERT INTO costobene_promociones_productos(promocion_id,producto_id) VALUES(?,?)'); foreach($targets as $t)$ins->execute([$promoId,(int)$t['id']]); }
  $pdo->commit();$ok='Promoción creada correctamente.';
 } elseif($accion==='estado') { if(!puede('gestionar_promociones'))throw new RuntimeException('No tenés permiso para modificar promociones.');$id=(int)($_POST['id']??0);$estado=(string)($_POST['estado']??'');if(!in_array($estado,['pausada','programada'],true))throw new RuntimeException('Estado inválido.');$q=db()->prepare('UPDATE costobene_promociones SET estado=? WHERE id=? AND cliente_id=?');$q->execute([$estado,$id,$clienteId]);$ok='Estado de la promoción actualizado.'; }
 }catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la promoción. Verificá la migración SQL.';}}
$q=db()->prepare("SELECT p.*, (SELECT COUNT(*) FROM costobene_promociones_productos pp WHERE pp.promocion_id=p.id) cantidad_productos FROM costobene_promociones p WHERE p.cliente_id=? ORDER BY p.id DESC");$q->execute([$clienteId]);$promos=$q->fetchAll();$mQ=db()->prepare('SELECT margen_minimo FROM costobene_clientes WHERE id=?');$mQ->execute([$clienteId]);$margenMin=(float)$mQ->fetchColumn();$csrf=csrfToken('csrf_promociones');$paginaActual='promociones';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Promociones - CostoPyme</title><link rel="stylesheet" href="style.css"></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main"><header class="page-head"><div><h1>Promociones y descuentos</h1><p>Aplicá promociones a productos y servicios individuales o a todo tu catálogo.</p></div></header>
<?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if($ok):?><div class="success"><?=h($ok)?></div><?php endif;?>
<?php if(puede('gestionar_promociones')):?><section class="panel"><h2>Configuración de rentabilidad</h2><?php if(esAdministrador()):?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="margen"><label>Margen mínimo permitido (%)<input type="number" name="margen_minimo" min="0" max="90" step="0.01" value="<?=h((string)($margenMin??10))?>" required></label><div class="actions"><button type="submit">Guardar margen mínimo</button></div></form><?php else:?><p class="help">El margen mínimo de seguridad lo configura el administrador.</p><?php endif;?></section>
<section class="panel"><h2>Nueva promoción</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="crear"><div class="form-grid"><label class="full">Nombre de la promoción *<input name="nombre" maxlength="150" required placeholder="Ej. Semana de descuentos"></label><label>Tipo *<select name="tipo" id="tipoPromo"><option value="porcentaje">Descuento porcentual</option><option value="fijo">Descuento por importe fijo</option><option value="mayorista">Precio mayorista por cantidad</option><option value="combo">Combo / unidades bonificadas</option></select></label><label><span id="valorPromoLabel">Descuento (%) *</span><input type="number" name="valor" min="0.01" step="0.01" required></label><label id="minimoBox" hidden>Cantidad mínima<input type="number" name="cantidad_minima" min="0.01" step="0.01"></label><label id="bonifBox" hidden>Unidades bonificadas<input type="number" name="cantidad_bonificada" min="0.01" step="0.01"></label><label>Fecha de inicio *<input type="date" name="fecha_inicio" required value="<?=date('Y-m-d')?>"></label><label>Fecha de finalización *<input type="date" name="fecha_fin" required value="<?=date('Y-m-d',strtotime('+7 days'))?>"></label></div>
<h3>¿A qué productos o servicios querés aplicarla?</h3><div class="choice-row"><label><input type="radio" name="alcance" value="individual" checked onchange="toggleAlcance()"> Individualmente</label><label><input type="radio" name="alcance" value="todos" onchange="toggleAlcance()"> A todos los productos y servicios</label></div><div id="selectorProductos"><label>Seleccioná uno o varios productos / servicios *<select name="productos[]" multiple size="6"><?php foreach($productos as $pr):?><option value="<?=(int)$pr['id']?>"><?=h($pr['nombre'])?> · <?=h($pr['moneda'])?></option><?php endforeach;?></select></label></div><label class="checkbox-label" id="futurosLabel"><input type="checkbox" name="incluir_futuros" id="incluirFuturos" value="1"> Incluir automáticamente los nuevos productos y servicios que se registren.</label><p class="help">Si hay una promoción individual y otra general vigentes para el mismo producto, prevalecerá la individual. Los descuentos no se acumulan.</p><div class="actions"><button type="submit">Guardar promoción</button></div></form></section><?php endif;?>
<section class="panel"><h2>Promociones registradas</h2><?php if(!$promos):?><div class="empty">Todavía no hay promociones creadas.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Promoción</th><th>Tipo</th><th>Aplicación</th><th>Valor</th><th>Vigencia</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($promos as $pr):$estado=$pr['estado'];if($estado!=='pausada')$estado=date('Y-m-d')<$pr['fecha_inicio']?'programada':(date('Y-m-d')>$pr['fecha_fin']?'vencida':'activa');?><tr><td><?=h($pr['nombre'])?></td><td><?=h($pr['tipo'])?></td><td><?=$pr['alcance']==='todos'?'Todo el catálogo':((int)$pr['cantidad_productos'].' seleccionados')?></td><td><?=number_format((float)$pr['valor'],2,',','.')?><?=$pr['tipo']==='porcentaje'?'%':''?></td><td><?=h($pr['fecha_inicio'])?> al <?=h($pr['fecha_fin'])?></td><td><span class="pill"><?=h($estado)?></span></td><td><?php if(puede('gestionar_promociones')&&$estado!=='vencida'):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=(int)$pr['id']?>"><input type="hidden" name="estado" value="<?=$estado==='pausada'?'programada':'pausada'?>"><button class="btn-secondary"><?=$estado==='pausada'?'Reanudar':'Pausar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
</main></div><script>function toggleAlcance(){const all=document.querySelector('input[name="alcance"]:checked').value==='todos';document.getElementById('selectorProductos').hidden=all;document.querySelector('select[name="productos[]"]').disabled=all;document.querySelector('select[name="productos[]"]').required=!all;document.getElementById('futurosLabel').hidden=!all;document.getElementById('incluirFuturos').disabled=!all;}document.getElementById('tipoPromo').addEventListener('change',e=>{document.getElementById('minimoBox').hidden=e.target.value!=='mayorista';document.getElementById('bonifBox').hidden=e.target.value!=='combo';document.getElementById('valorPromoLabel').textContent=({porcentaje:'Descuento (%) *',fijo:'Importe a descontar ($) *',mayorista:'Descuento mayorista (%) *',combo:'Unidades por compra *'})[e.target.value];});toggleAlcance();</script></body></html>
